head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil00175";
scwin.ansFormObj = undefined;

// TODO Stage2: 세션 키 실환경 확인(회신 11항) — session.user.usrTpCd

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        scwin.init_conds();
        scwin.init_sessionFill();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil00175.onpageload' });
    }
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "if_usrTpCd", fn: function(){ return ($c.session.getUserInfo("usrTpCd") === '3'); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        const ok = !!b.fn();
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "ipt_method", fn: function () { return String((dma_pageContext.get("method") ?? "")); } },
        { childId: "__rb0", fn: function () { return "전체 " + String(dma_docPage.get("total")) + "건 (" + String(dma_docPage.get("currentPage")) + "/ 0 " + String(dma_docPage.get("endListPage")) + " 페이지) "; } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { /* TODO Stage2: [sdd] 행 복사 대상 부재:  it.childId */ continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

// 세션 사용자 결선 (어휘 session_attribute 1건 — gcc $c.session.getUserInfo)

/**
 * @method
 * @name init_sessionFill
 * @description 초기화 — session Fill
 * @returns {void}
 * @hidden N
 */
scwin.init_sessionFill = function () {
    const names = ["usrTpCd"];
    function fill() {
        for (let i = 0; i < names.length; i++) {
            let v; try { v = $c.session.getUserInfo(names[i]); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil00175' }); v = undefined; }
            if (v === undefined || v === null || v === '') { continue; }
            const token = '${session.user.' + names[i] + '}';
            let r0 = ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document); r0 = r0.body || r0; const doc = r0.ownerDocument || r0; const w = doc.createTreeWalker(r0, NodeFilter.SHOW_TEXT);
            let n; while ((n = w.nextNode())) { if (n.nodeValue.indexOf(token) >= 0) { n.nodeValue = n.nodeValue.split(token).join(v); } }
            const ins = ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelectorAll('input, textarea');
            for (let j = 0; j < ins.length; j++) { if (ins[j].value && ins[j].value.indexOf(token) >= 0) { ins[j].value = ins[j].value.split(token).join(v); } }
        }
    }
    fill();
};

// [A] 초기 목록 미해결 — jldfil00175: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name img_70_onclick
 * @description img_70 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.img_70_onclick = function(e){
    try {
        fn_ViewManualKeyWord(0200000015)

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil00175.img_70_onclick' }); }
};

/**
 * @method
 * @name cal_searchBeginDd_onblur
 * @description cal_searchBeginDd 포커스 이탈 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.cal_searchBeginDd_onblur = async function(e){
    try {
        await (async (c) => { const raw = String((c && c.getValue) ? (c.getValue() ?? "") : ""); if (raw.length === 0) { return true; } const v = raw.split("-").join("").split("/").join(""); if (c && c.setValue) { c.setValue(v); } const lbl = ""; const lp = lbl ? (lbl + ": ") : ""; if (v.length !== 8) { await $c.win.alert(lp + "날짜는 8 자리 YYYYMMDD 형식입니다."); if (c && c.focus) { c.focus(); } return false; } let digits = true; for (let i = 0; i < v.length; i++) { const ch = v.charAt(i); if (ch < "0" || ch > "9") { digits = false; break; } } if (!digits) { await $c.win.alert(lp + "숫자만 입력가능합니다."); if (c && c.focus) { c.focus(); } return false; } const mm = Number(v.substring(4, 6)); if (mm > 12 || mm < 1) { await $c.win.alert(lp + "달은 1 에서 12 사이여야 합니다."); if (c && c.focus) { c.focus(); } return false; } if (!$c.date.checkCalendarFormat(c, "yyyyMMdd", { clearOnInvalid: false })) { await $c.win.alert(lp + " 존재하지 않는 날짜입니다."); if (c && c.focus) { c.focus(); } return false; } return true; })($c.util.getComponent("cal_searchBeginDd"));

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil00175.cal_searchBeginDd_onblur' }); }
};

/**
 * @method
 * @name cal_searchEndDd_onblur
 * @description cal_searchEndDd 포커스 이탈 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.cal_searchEndDd_onblur = async function(e){
    try {
        await (async (c) => { const raw = String((c && c.getValue) ? (c.getValue() ?? "") : ""); if (raw.length === 0) { return true; } const v = raw.split("-").join("").split("/").join(""); if (c && c.setValue) { c.setValue(v); } const lbl = ""; const lp = lbl ? (lbl + ": ") : ""; if (v.length !== 8) { await $c.win.alert(lp + "날짜는 8 자리 YYYYMMDD 형식입니다."); if (c && c.focus) { c.focus(); } return false; } let digits = true; for (let i = 0; i < v.length; i++) { const ch = v.charAt(i); if (ch < "0" || ch > "9") { digits = false; break; } } if (!digits) { await $c.win.alert(lp + "숫자만 입력가능합니다."); if (c && c.focus) { c.focus(); } return false; } const mm = Number(v.substring(4, 6)); if (mm > 12 || mm < 1) { await $c.win.alert(lp + "달은 1 에서 12 사이여야 합니다."); if (c && c.focus) { c.focus(); } return false; } if (!$c.date.checkCalendarFormat(c, "yyyyMMdd", { clearOnInvalid: false })) { await $c.win.alert(lp + " 존재하지 않는 날짜입니다."); if (c && c.focus) { c.focus(); } return false; } return true; })($c.util.getComponent("cal_searchEndDd"));

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil00175.cal_searchEndDd_onblur' }); }
};

/**
 * @method
 * @name img_100_onclick
 * @description img_100 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_100_onclick = async function(e){
    try {
        await scwin.searchList()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil00175.img_100_onclick' }); }
};

/**
 * @method
 * @name slc_pageSize_onchange
 * @description slc_pageSize 변경 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.slc_pageSize_onchange = async function(e){
    try {
        scwin.initPageIndex();await scwin.searchList()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil00175.slc_pageSize_onchange' }); }
};

/**
 * @method
 * @name grd_docPageList_oncellclick
 * @description grd_docPageList 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_docPageList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_docPageList');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_docPageList */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; } /* 수동 전환 필요: document.getElementById('${doc.acptNo}'+'_ansForm').style.display = 'none'; (EL 미해석) */
        scwin.viewAnsForm(r["acptNo"]); return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_docPageList.oncellclick' });
    }
};

/**
 * @method
 * @name krxpage_pagenavigator_162_onclick
 * @description krxpage_pagenavigator_162 클릭 이벤트
 * @param {Number} index index
 * @returns {void}
 * @hidden N
 */
scwin.krxpage_pagenavigator_162_onclick = async function (index) { const pi = (index && typeof index === 'object') ? index.newSelectedIndex : index; try { $c.util.getComponent('dma_searchListReq').set('pageIndex', pi); } catch (e) { $c.exception.handleError(e, { notify: 'none', context: 'krxpage_pagenavigator_162.page' }); } await scwin.searchList(); };

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_searchList
 * @description search List 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_searchList = async function () {
    const sbmOptions = {
        id: "tx_fn_searchList",
        method: "post",
        action: "/submission/searchDisclosureDocument.do",
        ref: "dma_searchListReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_documentWrite
 * @description document Write 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_documentWrite = async function () {
    const sbmOptions = {
        id: "tx_fn_documentWrite",
        method: "post",
        action: "/submission/disclosure.do?method=searchDisclosureDocument",
        ref: "dma_documentWriteReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_goWrite
 * @description go Write 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_goWrite = async function () {
    const sbmOptions = {
        id: "tx_fn_goWrite",
        method: "post",
        action: "/submission/disclosure.do?method=findDsclCorpIsuDigital&digitalType=2",
        ref: "dma_goWriteReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name initPageIndex
 * @description init Page Index 처리
 * @returns {void}
 * @hidden N
 */
scwin.initPageIndex = function () {
    $c.util.getComponent('dma_searchListReq').set('pageIndex', "1");
};

/**
 * @method
 * @name grd_docPageList_fmt_formKorNm
 * @description grd doc Page List fmt form Kor Nm 처리
 * @param {*} data 데이터
 * @param {*} formattedData 포맷된 값
 * @param {*} r r
 * @param {*} c c
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_docPageList_fmt_formKorNm = async function (data, formattedData, r, c) {
    try {
        const dl = $c.util.getComponent("dlt_docPageList");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "langTpCd") ?? '') : '');
        if (v === '0') { return String((dl && dl.getCellData ? dl.getCellData(r, "formKorNm") : '') ?? ''); }
        return (console.error('[sdd] 미실현 라벨 갈래: formKorNm (expression)'), String(data ?? ''));
    } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: "grd_docPageList.formKorNm" }); return String(data ?? ''); }
};

/**
 * @method
 * @name searchList
 * @description search List 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchList = async function () {
    const frm = (document.searchForm || { elements: [] });
    if ($c.util.getComponent('cal_searchBeginDd').getValue()> $c.util.getComponent('cal_searchEndDd').getValue()) {
        await $c.win.alert('시작일이 종료일보다 이후 일자 입니다.');
        return;
    }
    frm.action = "/submission/searchDisclosureDocument.do";
    await scwin.tx_fn_searchList();
};

/**
 * @method
 * @name documentWrite
 * @description document Write 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.documentWrite = async function () {
    (document.writeForm || { elements: [] }).action = '/submission/disclosure.do?method=searchDisclosureDocument';
    await scwin.tx_fn_documentWrite();
};

/**
 * @method
 * @name registerProcess
 * @description register Process 처리
 * @param {*} applNo applNo
 * @param {*} docNo docNo
 * @param {String} formCd formCd
 * @param {*} formVer formVer
 * @param {String} wrtrptMaindocTpCd wrtrptMaindocTpCd
 * @param {*} method method
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.registerProcess = async function (applNo, docNo, formCd, formVer, wrtrptMaindocTpCd, method) {
    $c.util.getComponent('dma_searchListReq').set('applNo', applNo);
    if (applNo.length === 14) {
        await scwin.documentWrite();
    } else {
        await scwin.registerMessage('문서불러오기에 실패하였습니다. 잠시후 다시 해주시기 바랍니다.');
    }
};

/**
 * @method
 * @name registerMessage
 * @description register Message 처리
 * @param {String} msg 항목명
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.registerMessage = async function (msg) {
    await $c.win.alert(msg);
};

/**
 * @method
 * @name goWrite
 * @description go Write 처리
 * @param {*} acptNo acptNo
 * @param {String} formCd formCd
 * @param {*} formVer formVer
 * @param {String} langTpCd langTpCd
 * @param {String} formUpclssCd formUpclssCd
 * @param {String} rsnClssCd rsnClssCd
 * @param {String} applFormYn applFormYn
 * @param {String} ldMktTpCd ldMktTpCd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.goWrite = async function (acptNo, formCd, formVer, langTpCd, formUpclssCd, rsnClssCd, applFormYn, ldMktTpCd) {
    $c.util.getComponent('dma_searchListReq').set('disclsMaindocFormCd', formCd);
    $c.util.getComponent('dma_searchListReq').set('disclsMaindocFormVer', formVer);
    $c.util.getComponent('dma_searchListReq').set('formCd', formCd);
    $c.util.getComponent('dma_searchListReq').set('formVer', formVer);
    $c.util.getComponent('dma_searchListReq').set('langTpCd', langTpCd);
    $c.util.getComponent('dma_searchListReq').set('formUpclssCd', formUpclssCd);
    $c.util.getComponent('dma_searchListReq').set('rsnClssCd', rsnClssCd);
    $c.util.getComponent('dma_searchListReq').set('inqOrgnDisclsAcptNo', acptNo);
    $c.util.getComponent('dma_searchListReq').set('ldMktTpCd', ldMktTpCd);
    $c.util.getComponent('dma_searchListReq').set('disclsMaindocFormCd', formCd);
    $c.util.getComponent('dma_searchListReq').set('disclsMaindocFormVer', formVer);
    $c.util.getComponent('dma_searchListReq').set('formCd', formCd);
    $c.util.getComponent('dma_searchListReq').set('formVer', formVer);
    $c.util.getComponent('dma_searchListReq').set('langTpCd', langTpCd);
    $c.util.getComponent('dma_searchListReq').set('formUpclssCd', formUpclssCd);
    $c.util.getComponent('dma_searchListReq').set('rsnClssCd', rsnClssCd);
    $c.util.getComponent('dma_searchListReq').set('inqOrgnDisclsAcptNo', acptNo);
    $c.util.getComponent('dma_searchListReq').set('ldMktTpCd', ldMktTpCd);
    let acptApplTpCd = 'D';
    if (applFormYn === 'Y') {
        acptApplTpCd = 'L';
    }
    $c.util.getComponent('dma_searchListReq').set('acptApplTpCd', acptApplTpCd);
    $c.util.getComponent('dma_searchListReq').set('acptApplTpCd', acptApplTpCd);
    let engFormYn = 'N';
    if (langTpCd === '1') {
        engFormYn = 'Y';
    }
    $c.util.getComponent('dma_searchListReq').set('engFormYn', engFormYn);
    $c.util.getComponent('dma_searchListReq').set('engFormYn', engFormYn);
    if ((String(($c.session.getUserInfo("usrTpCd")) === null ? '' : ($c.session.getUserInfo("usrTpCd"))).indexOf('$' + '{') >= 0 ? '' : String(($c.session.getUserInfo("usrTpCd")) === null ? '' : ($c.session.getUserInfo("usrTpCd")))) === '3') {
        if ('69530' === formCd || '69531' === formCd) {
            (document.writeForm || { elements: [] }).action = '/submission/disclosure.do?method=findDsclCorpIsuDigital&digitalType=2';
            await scwin.tx_fn_goWrite();
        } else {
            (document.disclosureFrm || { elements: [] }).action = '/submission/disclosurereg.do?method=registerDisclosure';
            (document.disclosureFrm || { elements: [] }).target = 'tempSaveFrame';
            await scwin.tx_fn_goWrite();
        }
    } else {
        if ('69530' === formCd || '69531' === formCd) {
            (document.writeForm || { elements: [] }).action = '/submission/disclosure.do?method=findDsclCorpIsuDigital&digitalType=3';
            await scwin.tx_fn_goWrite();
        } else {
            (document.writeForm || { elements: [] }).action = '/submission/disclosure.do?method=findDsclCorpIsuDigital&digitalType=1';
            await scwin.tx_fn_goWrite();
        }
    }
};

/**
 * @method
 * @name viewAnsForm
 * @description view Ans Form 처리
 * @param {String} divId divId
 * @returns {void}
 * @hidden N
 */
scwin.viewAnsForm = function (divId) {
    if (scwin.ansFormObj !== null && scwin.ansFormObj !== 'undefined') {
        scwin.ansFormObj.style.display = 'none';
    }
    if ($c.util.getComponent(divId + '_ansForm').getStyle('display') === 'none') {
        ($c.util.getComponent(divId + '_ansForm') && $c.util.getComponent(divId + '_ansForm').show ? $c.util.getComponent(divId + '_ansForm').show() : console.warn('[sdd] show 대상 미해결: ' + divId + '_ansForm'));
    } else {
        ($c.util.getComponent(divId + '_ansForm') && $c.util.getComponent(divId + '_ansForm').hide ? $c.util.getComponent(divId + '_ansForm').hide() : console.warn('[sdd] hide 대상 미해결: ' + divId + '_ansForm'));
    }
    scwin.ansFormObj = $c.util.getComponent(divId + '_ansForm');
};

/**
 * @method
 * @name goNewWrite
 * @description go New Write 처리
 * @returns {void}
 * @hidden N
 */
scwin.goNewWrite = function () {
    $c.win.setPageFrameSrc($c.win.getFrame(), '/jldfil00000/jldfil00000.xml');
};
